 * @param string $order A string indicating the order ('asc' for ascending or 'desc' for descending).
 * @return array The sorted array.
 */
function smart_sort_array(array $set, string $order): array {
    usort($set, function ($a, $b) use ($order) {
        if (empty($a['age']) || empty($b['age'])) {
            throw new Exception("Age cannot be empty");
        }

        return strcmp($a['age'], $b['age']);
    });

    // If order is not provided or invalid, default to ascending
    if (empty($order)) {
        $order = 'asc';
    } elseif (!in_array(strtolower($order), ['asc', 'desc'])) {
        throw new Exception("Invalid order: {$order}");
    }

    switch ($order) {
        case 'asc':
            return $set;
        case 'desc':
            return array_reverse($set);
        default:
            throw new Exception("Order must be either 'asc' or 'desc'");
    }
}

